public class MainActivity extends Activity {
 final int GREEN=Color.rgb(49,92,77),INK=Color.rgb(37,61,53),BG=Color.rgb(248,249,245);
 final String[] cats={"ทั้งหมด","หัวใจและหลอดเลือด","ต่อมไร้ท่อ","โรคติดเชื้อ","ระบบทางเดินหายใจ","ระบบทางเดินอาหาร","อื่น ๆ"};
 ArrayList<JSONObject> docs=new ArrayList<>(); LinearLayout root,list; String query="",filter="ทั้งหมด"; boolean favorites=false; JSONObject active; int page=0; PdfRenderer renderer; ParcelFileDescriptor descriptor; Bitmap bitmap; ImageView image;TextView pageLabel;Button prev,next; boolean busy=false;
 int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});try{File f=new File(getFilesDir(),"library.json");if(f.exists()){JSONArray a=new JSONArray(new String(new AtomicFile(f).readFully(),StandardCharsets.UTF_8));for(int i=0;i<a.length();i++)docs.add(a.getJSONObject(i));}}catch(Exception e){toast("อ่านคลังข้อมูลไม่ได้ กรุณาเก็บข้อมูลแอปไว้และติดต่อผู้พัฒนา");}home();UpdateChecker.check(this,false);if(b!=null){String id=b.getString("document");for(JSONObject d:docs)if(d.optString("id").equals(id)){open(d,b.getInt("page",0));break;}}}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(active!=null){b.putString("document",active.optString("id"));b.putInt("page",page);}}
 boolean persist(){try{JSONArray a=new JSONArray();for(JSONObject d:docs)a.put(d);AtomicFile af=new AtomicFile(new File(getFilesDir(),"library.json"));FileOutputStream out=null;try{out=af.startWrite();out.write(a.toString().getBytes(StandardCharsets.UTF_8));af.finishWrite(out);}catch(Exception e){af.failWrite(out);throw e;}return true;}catch(Exception e){toast("บันทึกไม่ได้ กรุณาตรวจสอบพื้นที่ว่าง");return false;}}
 LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
 LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.HORIZONTAL);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));return d;}
 Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(GREEN);b.setOnClickListener(v->action.run());return b;}
 void base(){root=column();root.setPadding(dp(20),dp(14),dp(20),dp(8));root.setBackgroundColor(BG);setContentView(root);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void home(){closePdf();active=null;base();LinearLayout heading=row();TextView brand=text("✚ pharmnote.",27,GREEN);brand.setTypeface(null,1);heading.addView(brand,new LinearLayout.LayoutParams(0,-2,1));heading.addView(button("⋮",this::menu));root.addView(heading);root.addView(text("คลัง Guideline ของฉัน",23,INK));root.addView(text("เก็บ PDF • อ่านฉบับเต็ม • สรุปเพื่อทบทวน",13,Color.GRAY));LinearLayout actions=row();actions.addView(button("＋ เพิ่ม PDF",()->pickPdf()),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button(favorites?"★ เฉพาะโปรด":"☆ ทั้งหมด",()->{favorites=!favorites;home();}),new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("ค้นหาโรค / guideline / องค์กร");search.setText(query);root.addView(search);Spinner category=new Spinner(this);category.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cats));category.setSelection(Arrays.asList(cats).indexOf(filter));root.addView(category);ScrollView scroll=new ScrollView(this);list=column();scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.addView(text("ข้อมูลเก็บในมือถือเครื่องนี้ • ควรสำรองก่อนลบแอป\nสำหรับการเรียนรู้ ตรวจทานกับ guideline ต้นฉบับ",11,Color.GRAY));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();render();}public void afterTextChanged(Editable e){}});category.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){filter=cats[pos];render();}});render();}
 void menu(){new AlertDialog.Builder(this).setTitle("Pharmnote "+BuildConfig.VERSION_NAME).setItems(new String[]{"ตรวจสอบอัปเดต","ตั้งค่าแหล่งอัปเดต GitHub","ส่งออกข้อมูลสำรอง"},(d,which)->{if(which==0)UpdateChecker.check(this,true);if(which==1)UpdateChecker.configure(this);if(which==2)exportBackup();}).show();}
 void render(){list.removeAllViews();int count=0;for(JSONObject d:docs){String hay=(d.optString("title")+d.optString("org")+d.optString("category")).toLowerCase(Locale.ROOT);if(!hay.contains(query.toLowerCase(Locale.ROOT))||(!filter.equals("ทั้งหมด")&&!filter.equals(d.optString("category")))||(favorites&&!d.optBoolean("favorite")))continue;count++;LinearLayout card=column();card.setPadding(dp(16),dp(12),dp(16),dp(12));card.setBackground(shape(Color.WHITE));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(12),0,0);list.addView(card,cp);card.addView(text(d.optString("category")+" · "+d.optString("year"),11,GREEN));TextView title=text(d.optString("title"),18,INK);title.setTypeface(null,1);card.addView(title);card.addView(text(d.optString("org"),12,Color.GRAY));LinearLayout bar=row();bar.addView(button("เปิดอ่าน ↗",()->open(d,0)),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button(d.optBoolean("favorite")?"★":"☆",()->{boolean old=d.optBoolean("favorite");try{d.put("favorite",!old);if(!persist())d.put("favorite",old);render();}catch(Exception ignored){}}));card.addView(bar);}if(count==0){LinearLayout welcome=column();welcome.setPadding(dp(12),dp(40),dp(12),dp(30));welcome.addView(text(docs.isEmpty()?"เริ่มต้นคลังความรู้ของคุณ":"ยังไม่มีเอกสารที่ตรงกัน",21,GREEN));welcome.addView(text("เพิ่ม guideline เป็น PDF เพื่อเปิดอ่านและเก็บคำอธิบายหรือสรุป regimen ไว้คู่กัน",14,Color.GRAY));welcome.addView(button("＋ เลือก PDF จากมือถือ",()->pickPdf()));list.addView(welcome);}}
 void pickPdf(){if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(request==1)importPdf(data.getData());if(request==2)writeBackup(data.getData());}
 void importPdf(Uri uri){busy=true;toast("กำลังนำเข้า PDF…");new Thread(()->{String id=UUID.randomUUID().toString();File file=new File(getFilesDir(),id+".pdf");try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException();byte[] buf=new byte[8192];int n;long total=0;while((n=in.read(buf))!=-1){total+=n;if(total>50L*1024*1024)throw new IOException("ใหญ่เกิน 50 MB");out.write(buf,0,n);}}try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd)){if(pdf.getPageCount()<1)throw new IOException();}runOnUiThread(()->{busy=false;metadata(id,file);});}catch(Exception e){file.delete();runOnUiThread(()->{busy=false;toast("นำเข้าไม่ได้: PDF อาจเสียหาย มีรหัสผ่าน หรือใหญ่เกิน 50 MB");});}}).start();}
 EditText field(LinearLayout parent,String label,String value,boolean multiline){parent.addView(text(label,12,GREEN));EditText e=new EditText(this);e.setText(value);e.setTextSize(14);e.setSingleLine(!multiline);if(multiline){e.setMinLines(5);e.setGravity(Gravity.TOP);}parent.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 void metadata(String id,File file){LinearLayout form=column();form.setPadding(dp(20),0,dp(20),0);EditText title=field(form,"ชื่อ Guideline","",false);EditText org=field(form,"องค์กร / แหล่งที่มา","",false);EditText year=field(form,"ปีที่เผยแพร่","",false);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Arrays.copyOfRange(cats,1,cats.length)));form.addView(spinner);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("เพิ่ม Guideline").setView(form).setNegativeButton("ยกเลิก",(a,b)->file.delete()).setPositiveButton("บันทึก",null).create();dialog.setOnCancelListener(a->file.delete());dialog.setOnShowListener(a->dialog.getButton(-1).setOnClickListener(v->{if(title.getText().toString().trim().isEmpty()){title.setError("กรุณาระบุชื่อ");return;}try{JSONObject d=new JSONObject().put("id",id).put("title",title.getText().toString().trim()).put("org",org.getText()).put("year",year.getText()).put("category",spinner.getSelectedItem().toString()).put("notes",new JSONObject());docs.add(0,d);if(persist()){dialog.dismiss();home();}else docs.remove(d);}catch(Exception e){toast("เพิ่มเอกสารไม่สำเร็จ");}}));dialog.show();}
 void open(JSONObject d,int initial){closePdf();try{descriptor=ParcelFileDescriptor.open(new File(getFilesDir(),d.optString("id")+".pdf"),ParcelFileDescriptor.MODE_READ_ONLY);renderer=new PdfRenderer(descriptor);active=d;page=Math.max(0,Math.min(initial,renderer.getPageCount()-1));base();LinearLayout top=row();top.addView(button("‹ คลัง",this::home));TextView title=text(d.optString("title"),16,INK);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);LinearLayout tools=row();tools.addView(button("✧ อธิบาย",()->study("explain")),new LinearLayout.LayoutParams(0,-2,1));tools.addView(button("สรุป Regimen",()->study("regimen")),new LinearLayout.LayoutParams(0,-2,1));root.addView(tools);ScrollView sc=new ScrollView(this);image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);sc.addView(image,new ScrollView.LayoutParams(-1,-2));root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout pages=row();prev=button("‹ ก่อนหน้า",()->{page--;renderPage();sc.scrollTo(0,0);});next=button("ถัดไป ›",()->{page++;renderPage();sc.scrollTo(0,0);});pageLabel=text("",12,INK);pageLabel.setGravity(Gravity.CENTER);pages.addView(prev);pages.addView(pageLabel,new LinearLayout.LayoutParams(0,-2,1));pages.addView(next);root.addView(pages);root.addView(button("เปิดด้วยแอป PDF อื่น / ขยายอ่าน",()->externalPdf()));root.addView(button("ลบเอกสาร",()->new AlertDialog.Builder(this).setTitle("ลบ PDF และสรุปทั้งหมด?").setMessage("การลบนี้ย้อนกลับไม่ได้").setNegativeButton("ยกเลิก",null).setPositiveButton("ลบ",(a,b)->{int pos=docs.indexOf(d);docs.remove(d);if(persist()){home();new File(getFilesDir(),d.optString("id")+".pdf").delete();}else docs.add(pos,d);}).show()));renderPage();}catch(Exception e){home();toast("เปิด PDF ไม่ได้ กรุณาลองเปิดด้วยแอปอื่น");}}
 void renderPage(){if(renderer==null)return;try(PdfRenderer.Page p=renderer.openPage(page)){int width=Math.min(1600,getResources().getDisplayMetrics().widthPixels*2);int height=Math.max(1,(int)((double)width*p.getHeight()/Math.max(1,p.getWidth())));if(height>7000){width=Math.max(1,width*7000/height);height=7000;}Bitmap nextBitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);nextBitmap.eraseColor(Color.WHITE);p.render(nextBitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(nextBitmap);if(bitmap!=null)bitmap.recycle();bitmap=nextBitmap;pageLabel.setText((page+1)+" / "+renderer.getPageCount());prev.setEnabled(page>0);next.setEnabled(page<renderer.getPageCount()-1);}catch(Exception|OutOfMemoryError e){toast("แสดงหน้านี้ไม่ได้ ลองเปิดด้วยแอป PDF อื่น");}}
 Uri pdfUri(){return Uri.parse("content://"+getPackageName()+".pdf/"+active.optString("id")+".pdf");}
 void externalPdf(){try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(pdfUri(),"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(ActivityNotFoundException e){toast("ยังไม่มีแอปเปิด PDF อื่นในเครื่อง");}}
 String prompt(String mode,String topic){return "ฉันเป็นนักศึกษาเภสัชศาสตร์ ใช้เฉพาะ PDF ที่แนบ: "+active.optString("title")+" ("+active.optString("year")+")\nหัวข้อ/หน้าที่สนใจ: "+topic+"\n"+(mode.equals("regimen")?"สรุป regimen เป็นตาราง: กลุ่มผู้ป่วย เงื่อนไข first-line ทางเลือก ขนาดยา วิธีให้ ความถี่ ระยะเวลา การปรับตามไต/ตับ ข้อห้าม monitoring":"อธิบายหลักการ เป้าหมายการรักษา เหตุผลการเลือกยา กลไก และประเด็นสำคัญให้เข้าใจง่าย")+"\nระบุหน้าอ้างอิงทุกข้อสำคัญ ไม่เติมขนาดยาหรือคำแนะนำที่เอกสารไม่ได้ระบุ หากข้อมูลขาดให้เขียนว่าไม่พบในเอกสาร หากไม่มีไฟล์แนบให้ขอ PDF ก่อนตอบ ใช้เพื่อการเรียน ไม่แทนการประเมินผู้ป่วยรายบุคคล";}
 void study(String mode){JSONObject notes=active.optJSONObject("notes");JSONObject n=notes==null?null:notes.optJSONObject(mode);LinearLayout form=column();form.setPadding(dp(20),0,dp(20),0);form.addView(text("เตรียมคำถามและแนบ PDF ไปยังแอป AI\nแอปนี้ยังไม่ได้เรียก AI โดยตรง",12,Color.GRAY));EditText topic=field(form,"หัวข้อ / หน้าที่สนใจ",n==null?"หน้า "+(page+1):n.optString("topic"),false);form.addView(button("คัดลอกคำถาม",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Pharmnote prompt",prompt(mode,topic.getText().toString())));toast("คัดลอกแล้ว กรุณาแนบ PDF เมื่อถาม AI");}));form.addView(button("ส่งคำถามพร้อม PDF ไปแอป AI",()->{Intent i=new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,pdfUri()).putExtra(Intent.EXTRA_TEXT,prompt(mode,topic.getText().toString())).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newUri(getContentResolver(),"Guideline",pdfUri()));try{startActivity(Intent.createChooser(i,"เลือก ChatGPT หรือแอป AI ที่ติดตั้ง"));}catch(Exception e){toast("ไม่พบแอปที่รองรับ ใช้การคัดลอกคำถามและแนบ PDF เอง");}}));EditText answer=field(form,"คำตอบจาก AI / สรุปของคุณ",n==null?"":n.optString("answer"),true);EditText refs=field(form,"หน้า / ตารางอ้างอิง",n==null?"":n.optString("pages"),false);CheckBox checked=new CheckBox(this);checked.setText("ตรวจทานกับเอกสารต้นฉบับแล้ว");checked.setTextSize(12);checked.setChecked(n!=null&&n.optBoolean("reviewed"));form.addView(checked);form.addView(text("ตรวจสอบขนาดยา ข้อห้าม และบริบทผู้ป่วยก่อนใช้ทางคลินิก",11,Color.GRAY));ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(mode.equals("regimen")?"สรุป Regimen":"อธิบายเนื้อหา").setView(scroll).setNegativeButton("ปิด",null).setPositiveButton("บันทึก",null).create();final String originalAnswer=answer.getText().toString(),originalTopic=topic.getText().toString(),originalRefs=refs.getText().toString();final boolean originalChecked=checked.isChecked();Runnable dismiss=()->{boolean changed=!answer.getText().toString().equals(originalAnswer)||!topic.getText().toString().equals(originalTopic)||!refs.getText().toString().equals(originalRefs)||checked.isChecked()!=originalChecked;if(changed)new AlertDialog.Builder(this).setMessage("มีข้อความที่ยังไม่บันทึก ต้องการทิ้งการแก้ไข?").setNegativeButton("กลับไปแก้",null).setPositiveButton("ทิ้ง",(a,b)->dialog.dismiss()).show();else dialog.dismiss();};dialog.setCancelable(false);dialog.setOnKeyListener((di,key,event)->{if(key==KeyEvent.KEYCODE_BACK&&event.getAction()==KeyEvent.ACTION_UP){dismiss.run();return true;}return key==KeyEvent.KEYCODE_BACK;});dialog.setOnShowListener(di->{dialog.getButton(-2).setOnClickListener(v->dismiss.run());dialog.getButton(-1).setOnClickListener(v->{try{JSONObject oldNotes=active.optJSONObject("notes");JSONObject all=oldNotes==null?new JSONObject():new JSONObject(oldNotes.toString());all.put(mode,new JSONObject().put("topic",topic.getText()).put("answer",answer.getText()).put("pages",refs.getText()).put("reviewed",checked.isChecked()));active.put("notes",all);if(persist()){toast("บันทึกสรุปแล้ว");dialog.dismiss();}else active.put("notes",oldNotes);}catch(Exception e){toast("บันทึกไม่ได้");}});});dialog.show();}
 void exportBackup(){if(busy){toast("กรุณารอการนำเข้าเอกสาร");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"pharmnote-backup-"+System.currentTimeMillis()+".zip");startActivityForResult(i,2);}
 void writeBackup(Uri uri){JSONArray snapshot=new JSONArray();ArrayList<String> ids=new ArrayList<>();for(JSONObject d:docs){snapshot.put(d);ids.add(d.optString("id"));}busy=true;toast("กำลังส่งออกข้อมูล…");new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt");ZipOutputStream zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry("library.json"));zip.write(snapshot.toString(2).getBytes(StandardCharsets.UTF_8));zip.closeEntry();byte[] buf=new byte[8192];for(String id:ids){zip.putNextEntry(new ZipEntry(id+".pdf"));try(InputStream in=new FileInputStream(new File(getFilesDir(),id+".pdf"))){int n;while((n=in.read(buf))!=-1)zip.write(buf,0,n);}zip.closeEntry();}runOnUiThread(()->{busy=false;toast("ส่งออก PDF และสรุปครบแล้ว");});}catch(Exception e){runOnUiThread(()->{busy=false;toast("ส่งออกไม่สำเร็จ กรุณาลองใหม่");});}}).start();}
 void closePdf(){if(image!=null)image.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}if(renderer!=null){renderer.close();renderer=null;}if(descriptor!=null){try{descriptor.close();}catch(Exception ignored){}descriptor=null;}}
 @Override public void onBackPressed(){if(active!=null)home();else super.onBackPressed();}
 protected void onDestroy(){closePdf();super.onDestroy();}
}
